    /// <param name = "e">form arguments</param>
    [
        FormControlEventHandler(formControlStr(VendParameters, METRDA_METRDAProcurementCategory), FormControlEventType::Lookup),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface'),
        SuppressBPWarningAttribute('BPUpgradeCodeLateBoundCall', 'Standard call')
    ]
    public static void METRDAProcurementCategory_OnLookUp(FormControl sender, FormControlEventArgs e)
